inline const BlockDef* findBlock(std::string_view opcode) {
    for (const auto& b : kBlockDefs) if (b.opcode == opcode) return &b;
    for (const auto& b : kExtensionDefs) if (b.opcode == opcode) return &b;
    return nullptr;
}

